from datetime import date, timedelta

def is_business_day(d: date, holidays=()) -> bool:
    hs = set(holidays)
    return d.weekday() < 5 and d not in hs

def adjust_business_day(d: date, holidays=(), convention: str = "modified_following") -> date:
    if not isinstance(convention, str):
        raise ValueError(convention)
    conv = convention.lower()
    if conv not in ("following", "modified_following", "preceding"):
        raise ValueError(convention)
    hs = set(holidays)
    if d.weekday() < 5 and d not in hs:
        return d
    if conv == "following":
        cur = d + timedelta(days=1)
        while not (cur.weekday() < 5 and cur not in hs):
            cur += timedelta(days=1)
        return cur
    if conv == "preceding":
        cur = d - timedelta(days=1)
        while not (cur.weekday() < 5 and cur not in hs):
            cur -= timedelta(days=1)
        return cur
    # modified_following
    cur = d + timedelta(days=1)
    while not (cur.weekday() < 5 and cur not in hs):
        cur += timedelta(days=1)
    if cur.month != d.month:
        cur = d - timedelta(days=1)
        while not (cur.weekday() < 5 and cur not in hs):
            cur -= timedelta(days=1)
        return cur
    return cur

def add_business_days(start: date, n: int, holidays=()) -> date:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError(n)
    if n == 0:
        return start
    hs = set(holidays)
    step = timedelta(days=1) if n > 0 else timedelta(days=-1)
    remaining = abs(n)
    cur = start
    while remaining > 0:
        cur = cur + step
        if cur.weekday() < 5 and cur not in hs:
            remaining -= 1
    return cur
